DEFAULT_NAME = "General"


def default_departments(apps, schema_editor):
    """One department per organization, holding every existing schedule, employee and
    supervisor, so nothing changes until an admin adds more (D95). It can be renamed."""
    Organization = apps.get_model("core", "Organization")
    Department = apps.get_model("core", "Department")
    Membership = apps.get_model("core", "Membership")
    SupervisorDepartment = apps.get_model("core", "SupervisorDepartment")
    Employee = apps.get_model("people", "Employee")
    EmployeeDepartment = apps.get_model("people", "EmployeeDepartment")
    SchedulePeriod = apps.get_model("scheduling", "SchedulePeriod")
    for org in Organization.objects.all():
        dept, _ = Department.objects.get_or_create(organization=org, name=DEFAULT_NAME)
        SchedulePeriod.objects.filter(organization=org, department__isnull=True).update(department=dept)
        for employee in Employee.objects.filter(organization=org):
            EmployeeDepartment.objects.get_or_create(organization=org, employee=employee, department=dept)
        for membership in Membership.objects.filter(organization=org, role="supervisor"):
            SupervisorDepartment.objects.get_or_create(membership=membership, department=dept)


